public with sharing class ExchangeRateClient {

    public class ExchangeRateException extends Exception {}

    /**
     * Fetches live exchange rates for specified quote currencies relative to a base currency.
     * 
     * @param baseCurrency The base currency code (e.g., 'EUR').
     * @param quoteCurrencies A set of quote currency codes (e.g., {'USD', 'GBP'}).
     * @return A map containing the normalized quote currencies and their corresponding rates.
     * @throws ExchangeRateException if validation fails, the API returns a non-200 status, 
     *         or the response is malformed/incomplete.
     */
    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('Quote currencies set cannot be null or empty.');
        }

        // Normalise base currency
        String normBase = normalizeCurrency(baseCurrency);

        // Normalise quote currencies
        Set<String> normQuotes = new Set<String>();
        for (String quote : quoteCurrencies) {
            normQuotes.add(normalizeCurrency(quote));
        }

        // Build Request
        HttpRequest request = new HttpRequest();
        String symbols = String.join(new List<String>(normQuotes), ',');
        String endpoint = 'callout:FB_Exchange_Rates/v1/latest?base=' + normBase + '&symbols=' + symbols;

        request.setEndpoint(endpoint);
        request.setMethod('GET');
        request.setHeader('Accept', 'application/json');

        Http http = new Http();
        HttpResponse response = http.send(request);

        // Retry once if status is 503
        if (response.getStatusCode() == 503) {
            response = http.send(request);
        }

        // Validate final status
        if (response.getStatusCode() != 200) {
            throw new ExchangeRateException('API request failed with status code: ' + response.getStatusCode());
        }

        // Parse Response
        try {
            Map<String, Object> jsonResponse = (Map<String, Object>) JSON.deserializeUntyped(response.getBody());
            Map<String, Object> ratesMap = (Map<String, Object>) jsonResponse.get('rates');

            if (ratesMap == null) {
                throw new ExchangeRateException('The response body did not contain a rates map.');
            }

            Map<String, Decimal> results = new Map<String, Decimal>();
            for (String quote : normQuotes) {
                Object rateValue = ratesMap.get(quote);
                if (rateValue == null) {
                    throw new ExchangeRateException('The API response did not provide a rate for requested currency: ' + quote);
                }
                // JSON.deserializeUntyped returns numbers as Decimal or Double. 
                // Converting to String then Decimal is the safest way to ensure a Decimal return.
                results.put(quote, Decimal.valueOf(String.valueOf(rateValue)));
            }

            return results;
        } catch (ExchangeRateException e) {
            throw e;
        } catch (Exception e) {
            throw new ExchangeRateException('An error occurred while parsing the API response: ' + e.getMessage());
        }
    }

    /**
     * Trims, upper-cases, and validates that a currency code consists of exactly 3 letters A-Z.
     */
    private static String normalizeCurrency(String code) {
        if (code == null) {
            throw new ExchangeRateException('Currency code cannot be null.');
        }

        String normalized = code.trim().toUpperCase();

        // Regex checks for exactly 3 characters, all within A-Z using Pattern class
        if (!Pattern.compile('^[A-Z]{3}$').matcher(normalized).matches()) {
            throw new ExchangeRateException('Invalid currency code format: ' + code + '. Must be exactly 3 letters A-Z.');
        }

        return normalized;
    }
}
