/**
 * LogPurgeJob handles the periodic purging of FB_Integration_Log__c records
 * to prevent storage overflow. It implements Schedulable to allow for 
 * automated cleanup on a nightly basis.
 */
public class LogPurgeJob implements Schedulable {

    /**
     * No-argument constructor as required.
     */
    public LogPurgeJob() {
    }

    /**
     * Schedulable execute method.
     * Performs the deletion of integration logs based on the retention policy.
     * 
     * Retention Policy:
     * - Records with Level__c != 'ERROR' (including null/blank) are deleted if created > 30 days ago.
     * - Records with Level__c == 'ERROR' are deleted if created > 180 days ago.
     */
    public void execute(SchedulableContext sc) {
        DateTime thirtyDaysAgo = System.now().addDays(-30);
        DateTime oneEightyDaysAgo = System.now().addDays(-180);

        // Query records that meet the purge criteria.
        // In SOQL, the != operator excludes null values, so we explicitly 
        // include Level__c = null to ensure blank logs are purged after 30 days.
        List<FB_Integration_Log__c> logsToDelete = [
            SELECT Id 
            FROM FB_Integration_Log__c 
            WHERE ( (Level__c != 'ERROR' OR Level__c = null) AND CreatedDate < :thirtyDaysAgo )
               OR ( Level__c = 'ERROR' AND CreatedDate < :oneEightyDaysAgo )
        ];

        if (!logsToDelete.isEmpty()) {
            delete logsToDelete;
        }
    }

    /**
     * Schedules the LogPurgeJob to run every day at 02:00 AM.
     * 
     * @return The Job ID returned by the System.schedule call.
     */
    public static Id scheduleNightly() {
        // Cron expression: seconds, minutes, hours, day-of-month, month, day-of-week
        String cronExp = '0 0 2 * * ?';
        String jobName = 'Log purge (nightly)';
        return System.schedule(jobName, cronExp, new LogPurgeJob());
    }
}
