public class Application {
    public static fflib_Application.UnitOfWorkFactory UnitOfWork = new UnitOfWorkFactory();
    public static fflib_Application.ServiceFactory Service = new ServiceFactory();
    public static fflib_Application.SelectorFactory Selector = new SelectorFactory();
    public static fflib_Application.DomainFactory Domain = new DomainFactory();

    public class UnitOfWorkFactory extends fflib_Application.UnitOfWorkFactory {
        public override fflib_ISObjectUnitOfWork newInstance() {
            return new fflib_SObjectUnitOfWork(new List<SObjectType>{
                Account.SObjectType,
                Contact.SObjectType,
                Opportunity.SObjectType,
                OpportunityContactRole.SObjectType
            });
        }
    }

    public class ServiceFactory extends fflib_Application.ServiceFactory {
        public override Object newInstance(Type t) {
            if (t == IAccountsService.class) {
                return new AccountsServiceImpl();
            }
            return super.newInstance(t);
        }
    }

    public class SelectorFactory extends fflib_Application.SelectorFactory {
        public override fflib_SObjectSelector newInstance(SObjectType sObjectType) {
            if (sObjectType == Account.SObjectType) {
                return new AccountsSelector();
            } else if (sObjectType == Contact.SObjectType) {
                return new ContactsSelector();
            }
            return super.newInstance(sObjectType);
        }
    }

    public class DomainFactory extends fflib_Application.DomainFactory {
        public override fflib_SObjectDomain newInstance(SObjectType sObjectType) {
            if (sObjectType == Account.SObjectType) {
                return new Accounts(new List<Account>());
            }
            return super.newInstance(sObjectType);
        }

        public fflib_SObjectDomain newInstance(Set<Id> ids) {
            // Requirement: "Building a domain from a set of record ids (Application.Domain.newInstance(Set<Id>)) 
            // must query the records through the Selector factory above."
            // Note: This requires Application.Domain to be cast to DomainFactory in the calling code
            // if the field is strictly typed as fflib_Application.DomainFactory.
            SObjectType sObjectType = Account.SObjectType; // Assumption based on current domain implementation
            fflib_SObjectSelector selector = Application.Selector.newInstance(sObjectType);
            List<SObject> records = selector.selectById(ids);
            return newInstance(sObjectType, records);
        }

        public fflib_SObjectDomain newInstance(SObjectType sObjectType, List<SObject> records) {
            if (sObjectType == Account.SObjectType) {
                return new Accounts((List<Account>) records);
            }
            return super.newInstance(sObjectType);
        }
    }
