        List<Opportunity> opps = (List<Opportunity>)records;
        validateAmountNotNegative(opps);
        validateAmountLockedOnWon(opps, (Map<Id, Opportunity>)oldMap);
    }

    private void validateAmountNotNegative(List<Opportunity> records) {
        for (Opportunity opp : records) {
            if (opp.Amount != null && opp.Amount < 0) {
                this.error('Amount cannot be negative.', opp, 'Amount');
            }
        }
    }

    private void validateAmountLockedOnWon(List<Opportunity> records, Map<Id, Opportunity> oldMap) {
        for (Opportunity opp : records) {
            Opportunity oldOpp = oldMap.get(opp.Id);
            if (oldOpp != null && 'Closed Won'.equals(oldOpp.StageName) && opp.Amount != oldOpp.Amount) {
                this.error('Amount cannot change on a won opportunity.', opp, 'Amount');
            }
        }
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(SObject[] records) {
            return new Opportunities(records);
        }
    }
