                       ', (SELECT ' + String.join(contactFieldNames, ',') + ' FROM Contacts) ' + 
                       'FROM Account WHERE Id IN :accountIds';

        // selectSObjectsByQuery respects the selector's dataAccess setting (USER_MODE)
        return (List<Account>) selectSObjectsByQuery(query);
