    public static List<Account> createAccountsWithContacts(Map<String, List<String>> contactLastNamesByAccountName) {
        if (contactLastNamesByAccountName == null || contactLastNamesByAccountName.isEmpty()) {
            return new List<Account>();
        }

        // fflib_SObjectUnitOfWork requires a list of SObject types it will manage in its constructor
        fflib_SObjectUnitOfWork uow = new fflib_SObjectUnitOfWork(
            new List<SObjectType>{ Account.SObjectType, Contact.SObjectType }
        );

        List<Account> createdAccounts = new List<Account>();

        for (String accountName : contactLastNamesByAccountName.keySet()) {
            // Create the Account
            Account acc = new Account(Name = accountName);
            uow.registerNew(acc);
            createdAccounts.add(acc);

            // Create the associated Contacts
            List<String> lastNames = contactLastNamesByAccountName.get(accountName);
            if (lastNames != null) {
                for (String lastName : lastNames) {
                    Contact con = new Contact(LastName = lastName);
                    uow.registerNew(con);
                    // registerRelationship ensures the Account is inserted before the Contact 
                    // and assigns the AccountId to the Contact.
                    uow.registerRelationship(con, Contact.AccountId, acc);
                }
            }
        }

        // Execute all registered DML operations in the correct order
        uow.commitWork();

        return createdAccounts;
    }
}
