/**
 * Syncs Account records to the ERP system.
 * Implements Database.Batchable and Database.AllowsCallouts to handle bulk imports
 * (up to 200 records) while respecting the Salesforce limit of 100 callouts per transaction.
 */
public class ErpCustomerSync implements Database.Batchable<Account>, Database.AllowsCallouts {

    private List<Account> accountsToSync;

    public ErpCustomerSync(List<Account> accounts) {
        this.accountsToSync = accounts;
    }

    /**
     * Entry point called by the trigger.
     * Executes the batch with a size of 100 to ensure we stay within the callout limit.
     */
    public static void sync(List<Account> accounts) {
        if (accounts != null && !accounts.isEmpty()) {
            // We set batch size to 100 because Salesforce limits a single transaction to 100 callouts.
            // For 200 records, this will result in 2 batch executions.
            Database.executeBatch(new ErpCustomerSync(accounts), 100);
        }
    }

    public Iterable<Account> start(Database.BatchableContext bc) {
        return accountsToSync;
    }

    public void execute(Database.BatchableContext bc, List<Account> scope) {
        for (Account acc : scope) {
            sendToErp(acc);
        }
    }

    public void finish(Database.BatchableContext bc) {
        // No post-processing required.
    }

    /**
     * Performs a POST callout for a single account.
     * The payload is wrapped in a JSON array as required by the ERP API.
     */
    private void sendToErp(Account acc) {
        HttpRequest req = new HttpRequest();
        req.setEndpoint('callout:ERP/api/customers');
        req.setMethod('POST');
        req.setHeader('Content-Type', 'application/json');

        // Construct the request object
        ErpAccountRequest payload = new ErpAccountRequest(
            acc.Id, 
            acc.Name, 
            acc.BillingCountry
        );

        // The ERP API expects a JSON array of 1 to 200 customers
        List<ErpAccountRequest> bodyList = new List<ErpAccountRequest>{ payload };
        req.setBody(JSON.serialize(bodyList));

        Http http = new Http();
        try {
            http.send(req);
        } catch (Exception e) {
            // Error handling is out of scope, but we catch to prevent 
            // a single failed callout from failing the entire batch.
            System.debug('ERP Sync Error for Account ' + acc.Id + ': ' + e.getMessage());
        }
    }

    /**
     * Wrapper class to maintain correct JSON key naming during serialization.
     */
    private class ErpAccountRequest {
        public String salesforceId;
        public String name;
        public String country;

        public ErpAccountRequest(String sfId, String name, String country) {
            this.salesforceId = sfId;
            this.name = name;
            this.country = country;
        }
    }
}
