public with sharing class RenewalReminderService {
    /**
     * Sends renewal reminders to Opportunity owners.
     * 
     * @param opportunityIds List of Opportunity IDs to process.
     * @return The number of emails sent successfully.
     */
    public static Integer sendReminders(List<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        // Query necessary fields for the opportunities
        List<Opportunity> opportunities = [
            SELECT Name, OwnerId, CloseDate 
            FROM Opportunity 
            WHERE Id IN :opportunityIds
        ];

        if (opportunities.isEmpty()) {
            return 0;
        }

        List<Messaging.SingleEmailMessage> emailsToSend = new List<Messaging.SingleEmailMessage>();

        for (Opportunity opp : opportunities) {
            Messaging.SingleEmailMessage mail = new Messaging.SingleEmailMessage();

            // setTargetObjectId requires a User, Lead, or Contact ID.
            // emails to users by Id don't use the org's daily allocation for external emails.
            mail.setTargetObjectId(opp.OwnerId);
            mail.setSaveAsActivity(false);
            mail.setSubject('Renewal due: ' + opp.Name);
            mail.setPlainTextBody('The renewal for ' + opp.Name + ' is due on ' + opp.CloseDate);

            emailsToSend.add(mail);
        }

        Integer successfulEmails = 0;
        if (!emailsToSend.isEmpty()) {
            try {
                // Call Messaging.sendEmail once with the list to avoid the 10-invocation limit.
                // This is bulk-safe and can handle up to 10,000 emails in a single call.
                Messaging.SendEmailResult[] results = Messaging.sendEmail(emailsToSend);

                for (Messaging.SendEmailResult result : results) {
                    if (result.isSuccess()) {
                        successfulEmails++;
                    }
                }
            } catch (Exception e) {
                // Log the error; in a production scenario, consider a custom logging framework.
                System.debug(LoggingLevel.ERROR, 'Error sending bulk emails: ' + e.getMessage());
            }
        }

        return successfulEmails;
    }
}
