import { LightningElement, api, wire } from 'lwc';
import { updateRecord } from 'lightning/uiRecordApi';
import { refreshApex } from '@salesforce/apex';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import getContacts from '@salesforce/apex/ContactController.getContacts';

const COLUMNS = [
    { label: 'Name', fieldName: 'Name', type: 'text', editable: false },
    { label: 'Title', fieldName: 'Title', type: 'text', editable: true },
    { label: 'Phone', fieldName: 'Phone', type: 'phone', editable: true },
    { label: 'Email', fieldName: 'Email', type: 'email', editable: true },
];

export default class AccountContactsTable extends LightningElement {
    @api recordId;
    columns = COLUMNS;
    draftValues = [];
    contacts;
    wiredContactsResult;

    @wire(getContacts, { accountId: '$recordId' })
    wiredContacts(result) {
        this.wiredContactsResult = result;
        if (result.data) {
            this.contacts = result.data;
        } else if (result.error) {
            console.error('Error fetching contacts:', result.error);
        }
    }

    async handleSave(event) {
        const draftValues = event.detail.draftValues;

        try {
            // Map each draft row to an updateRecord promise using the requested input format { fields: { ...draft } }
            const promises = draftValues.map(draft => {
                return updateRecord({ 
                    fields: { ...draft } 
                });
            });

            // Execute all updates in parallel and wait for completion
            await Promise.all(promises);

            // Success handling: Toast -> Clear Drafts -> Refresh Apex
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Contacts updated',
                    variant: 'success'
                })
            );

            this.draftValues = [];
            await refreshApex(this.wiredContactsResult);

        } catch (error) {
            // Error handling: message = failure's body.message
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Could not save contacts',
                    message: error?.body?.message || 'Unknown error',
                    variant: 'error'
                })
            );
        }
    }
}
