import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

export default class QueueMonitor extends LightningElement {
    waiting;
    longestWaitMinutes;
    error;
    hasLoaded = false;
    isLoading = false;
    intervalId;

    REFRESH_INTERVAL = 60000;

    connectedCallback() {
        // 1. Load stats immediately upon insertion
        this.fetchStats();

        // 2. Set up polling every 60 seconds
        this.intervalId = setInterval(() => {
            this.fetchStats();
        }, this.REFRESH_INTERVAL);

        // 3. Listen for visibility changes to handle background tab requirements
        document.addEventListener('visibilitychange', this.handleVisibilityChange);
    }

    disconnectedCallback() {
        // 4. Cleanup: Stop all polling and remove listeners to prevent memory leaks/zombie requests
        if (this.intervalId) {
            clearInterval(this.intervalId);
        }
        document.removeEventListener('visibilitychange', this.handleVisibilityChange);
    }

    // Use arrow function to maintain 'this' context for the event listener
    handleVisibilityChange = () => {
        if (document.visibilityState === 'visible') {
            // Load immediately when the page becomes visible again
            this.fetchStats();
        }
    };

    async fetchStats() {
        // Requirement: Never start a request while the previous one is still in flight
        if (this.isLoading) {
            return;
        }

        // Requirement: While document.visibilityState is 'hidden', make no requests
        if (document.visibilityState === 'hidden') {
            return;
        }

        this.isLoading = true;

        try {
            const result = await getQueueStats();

            if (result) {
                this.waiting = result.waiting;
                this.longestWaitMinutes = result.longestWaitMinutes;
                this.hasLoaded = true;
                // Requirement: Remove error after the next successful refresh
                this.error = null;
            }
        } catch (err) {
            // Requirement: Render error.body.message if request fails
            this.error = err?.body?.message || err?.message || 'An unexpected error occurred';
        } finally {
            this.isLoading = false;
        }
    }
}
