import { LightningElement, api } from 'lwc';

export default class StatusListbox extends LightningElement {
    _value;
    _options = [];
    _activeIndex = 0;

    @api label;

    @api 
    get options() {
        return this._options;
    }

    set options(value) {
        this._options = value || [];
        this.syncActiveIndex();
        this.refreshProcessedOptions();
    }

    @api 
    get value() {
        return this._value;
    }

    set value(val) {
        this._value = val;
        this.syncActiveIndex();
        this.refreshProcessedOptions();
    }

    // Internal helper to derive the list for the template to ensure stability
    _processedOptions = [];
    refreshProcessedOptions() {
        this._processedOptions = this._options.map((opt, index) => ({
            ...opt,
            id: `option-${index}`,
            isSelected: opt.value === this._value
        }));
    }

    syncActiveIndex() {
        if (!this._options || this._options.length === 0) {
            this._activeIndex = 0;
            return;
        }
        const index = this._options.findIndex(opt => opt.value === this._value);
        this._activeIndex = index !== -1 ? index : 0;
    }

    get activeId() {
        return `option-${this._activeIndex}`;
    }

    get processedOptions() {
        return this._processedOptions;
    }

    handleKeyDown(event) {
        const { key } = event;
        let handled = false;

        switch (key) {
            case 'ArrowDown':
                if (this._activeIndex < this._options.length - 1) {
                    this._activeIndex++;
                    handled = true;
                }
                break;
            case 'ArrowUp':
                if (this._activeIndex > 0) {
                    this._activeIndex--;
                    handled = true;
                }
                break;
            case 'Home':
                this._activeIndex = 0;
                handled = true;
                break;
            case 'End':
                this._activeIndex = this._options.length - 1;
                handled = true;
                break;
            case 'Enter':
            case ' ':
                this.selectActive();
                handled = true;
                break;
        }

        if (handled) {
            event.preventDefault();
        }
    }

    handleOptionClick(event) {
        const optionElement = event.currentTarget;
        const value = optionElement.dataset.value;

        // Find index based on the value to synchronize activeIndex
        const index = this._options.findIndex(opt => opt.value === value);
        if (index !== -1) {
            this._activeIndex = index;
        }

        this.handleSelection(value);
    }

    selectActive() {
        const activeOption = this._options[this._activeIndex];
        if (activeOption) {
            this.handleSelection(activeOption.value);
        }
    }

    handleSelection(newValue) {
        if (newValue !== this._value) {
            this.dispatchEvent(new CustomEvent('change', {
                detail: { value: newValue }
            }));
        }
    }
}
