public with sharing class GiftImportService {

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // the donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;        // the matched or created contact
        public Id opportunityId;    // the created donation
        public String errorMessage; // NPSP's failure information when success is false
    }

    /**
     * Processes a list of web gifts using the NPSP Batch Data Import (BDI) engine.
     * 
     * @param gifts A list of WebGift wrapper objects to be imported.
     * @return A list of ImportResult objects corresponding to the input order.
     */
    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        if (gifts == null || gifts.isEmpty()) {
            return new List<ImportResult>();
        }

        // 1. Map WebGift objects to NPSP Data Import staging records
        List<npsp__DataImport__c> stagingRecords = new List<npsp__DataImport__c>();
        for (WebGift gift : gifts) {
            stagingRecords.add(new npsp__DataImport__c(
                npsp__Contact1_Firstname__c = gift.firstName,
                npsp__Contact1_Lastname__c = gift.lastName,
                npsp__Contact1_Personal_Email__c = gift.email,
                npsp__Donation_Amount__c = gift.amount,
                npsp__Donation_Date__c = gift.giftDate,
                npsp__Donation_Donor__c = 'Contact1' // Directs NPSP to match using the Contact1 fields
            ));
        }

        // 2. Insert staging records to create the audit trail
        insert stagingRecords;

        // 3. Process records synchronously in the same transaction using NPSP's Apex API.
        // This ensures NPSP's matching, householding, and donation rules are applied immediately.
        npsp.BDIProcess.process(stagingRecords);

        // 4. Re-query the staging records to retrieve the results produced by the BDI engine.
        // We use a map to maintain the relationship between original records and their processed state.
        Set<Id> stagingIds = new Map<Id, npsp__DataImport__c>(stagingRecords).keySet();
        Map<Id, npsp__DataImport__c> processedMap = new Map<Id, npsp__DataImport__c>(
            [
                SELECT Id, npsp__Status__c, npsp__Contact1Imported__c, 
                       npsp__DonationImported__c, npsp__FailureInformation__c 
                FROM npsp__DataImport__c 
                WHERE Id IN :stagingIds
            ]
        );

        // 5. Construct ImportResult list in the original input order
        List<ImportResult> results = new List<ImportResult>();
        for (npsp__DataImport__c stagingRecord : stagingRecords) {
            npsp__DataImport__c processed = processedMap.get(stagingRecord.Id);
            ImportResult res = new ImportResult();

            if (processed != null) {
                // NPSP marks the row as 'Imported' when the process completes successfully for that row.
                res.success = (processed.npsp__Status__c == 'Imported');
                res.contactId = processed.npsp__Contact1Imported__c;
                res.opportunityId = processed.npsp__DonationImported__c;
                res.errorMessage = processed.npsp__FailureInformation__c;
            } else {
                res.success = false;
                res.errorMessage = 'The staging record was not found after processing.';
            }

            results.add(res);
        }

        return results;
    }
}
