public with sharing class SoftCreditService {

    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    /**
     * Ensures fundraisers are credited for gifts using NPSP partial soft credits.
     * This service handles the creation/update of OpportunityContactRoles and 
     * the corresponding partial soft credit records.
     */
    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        Set<Id> oppIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        for (SoftCreditRequest req : requests) {
            oppIds.add(req.opportunityId);
            contactIds.add(req.contactId);
        }

        // Query 1: Opps for validation
        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>([
            SELECT Id, Amount, npsp__Primary_Contact__c 
            FROM Opportunity 
            WHERE Id IN :oppIds
        ]);

        // Query 2: All OCRs for the involved pairs to manage the "exactly one" rule
        Map<String, List<OpportunityContactRole>> ocrGroupMap = new Map<String, List<OpportunityContactRole>>();
        for (OpportunityContactRole ocr : [
            SELECT Id, OpportunityId, ContactId, Role 
            FROM OpportunityContactRole 
            WHERE OpportunityId IN :oppIds AND ContactId IN :contactIds
        ]) {
            String key = ocr.OpportunityId + '-' + ocr.ContactId;
            if (!ocrGroupMap.containsKey(key)) {
                ocrGroupMap.put(key, new List<OpportunityContactRole>());
            }
            ocrGroupMap.get(key).add(ocr);
        }

        // Query 3: Existing Partial Soft Credits
        Map<String, npsp__Partial_Soft_Credit__c> pscMap = new Map<String, npsp__Partial_Soft_Credit__c>();
        for (npsp__Partial_Soft_Credit__c psc : [
            SELECT Id, npsp__Opportunity__c, npsp__Contact__c 
            FROM npsp__Partial_Soft_Credit__c 
            WHERE npsp__Opportunity__c IN :oppIds AND npsp__Contact__c IN :contactIds
        ]) {
            String key = psc.npsp__Opportunity__c + '-' + psc.npsp__Contact__c;
            pscMap.put(key, psc);
        }

        // Validation Stage: Must complete for all requests before any DML
        for (SoftCreditRequest req : requests) {
            Opportunity opp = oppMap.get(req.opportunityId);
            if (opp == null) throw new SoftCreditException('Opportunity not found.');
            if (req.amount == null || req.amount <= 0) throw new SoftCreditException('Amount must be positive.');
            if (opp.npsp__Primary_Contact__c == req.contactId) throw new SoftCreditException('Contact cannot be the primary contact.');
            if (req.amount > (opp.Amount == null ? 0 : opp.Amount)) throw new SoftCreditException('Amount cannot exceed opportunity amount.');
        }

        // OCR Processing Stage
        Map<String, OpportunityContactRole> ocrToUpsertMap = new Map<String, OpportunityContactRole>();
        List<OpportunityContactRole> toDeleteOCR = new List<OpportunityContactRole>();

        for (SoftCreditRequest req : requests) {
            String key = req.opportunityId + '-' + req.contactId;
            List<OpportunityContactRole> existingRoles = ocrGroupMap.get(key);

            if (existingRoles == null || existingRoles.isEmpty()) {
                OpportunityContactRole newRole = new OpportunityContactRole(
                    OpportunityId = req.opportunityId, 
                    ContactId = req.contactId, 
                    Role = req.role
                );
                ocrToUpsertMap.put(key, newRole);
            } else {
                // Keep the first one, update its role, and mark others for deletion
                OpportunityContactRole mainRole = existingRoles[0];
                mainRole.Role = req.role;
                ocrToUpsertMap.put(key, mainRole);

                if (existingRoles.size() > 1) {
                    for (Integer i = 1; i < existingRoles.size(); i++) {
                        toDeleteOCR.add(existingRoles[i]);
                    }
                }
            }
        }

        // DML 1: Delete redundant roles
        if (!toDeleteOCR.isEmpty()) {
            delete toDeleteOCR;
        }
        // DML 2: Upsert the required roles to ensure IDs are generated/assigned
        if (!ocrToUpsertMap.isEmpty()) {
            upsert ocrToUpsertMap.values();
        }

        // Soft Credit Processing Stage
        List<npsp__Partial_Soft_Credit__c> toUpsertPSC = new List<npsp__Partial_Soft_Credit__c>();
        for (SoftCreditRequest req : requests) {
            String key = req.opportunityId + '-' + req.contactId;
            OpportunityContactRole targetRole = ocrToUpsertMap.get(key);

            npsp__Partial_Soft_Credit__c psc = pscMap.get(key);
            if (psc == null) {
                psc = new npsp__Partial_Soft_Credit__c();
                psc.npsp__Opportunity__c = req.opportunityId;
                psc.npsp__Contact__c = req.contactId;
            }

            psc.npsp__Amount__c = req.amount;
            psc.npsp__Role_Name__c = req.role;
            psc.npsp__Contact_Role_ID__c = targetRole.Id;
            toUpsertPSC.add(psc);
        }

        // DML 3: Upsert Soft Credits
        if (!toUpsertPSC.isEmpty()) {
            upsert toUpsertPSC;
        }
    }
}
