/**
 * @description Trigger Action to create an onboarding task when a new Account
 * is created with a specific Customer type.
 * 
 * This class implements TriggerAction.AfterInsert as requested by the
 * Trigger Actions Framework (TAF) to ensure logic executes in the 
 * after insert context.
 */
public class TA_Account_CreateOnboardingTask implements TriggerAction.AfterInsert {

    public void afterInsert(List<SObject> triggerNew) {
        List<Task> tasksToInsert = new List<Task>();

        for (SObject sobj : triggerNew) {
            Account acc = (Account) sobj;

            // Only create tasks for specific Customer types
            if (acc.Type == 'Customer - Direct' || acc.Type == 'Customer - Channel') {
                tasksToInsert.add(new Task(
                    Subject = 'Onboard new customer',
                    WhatId = acc.Id,
                    OwnerId = acc.OwnerId,
                    ActivityDate = Date.today().addDays(7),
                    Status = 'Not Started',
                    Priority = 'Normal'
                ));
            }
        }

        // Bulk-safe DML: perform insert only if there are tasks to insert
        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }
    }
}
