public with sharing class TA_Contact_PreventDuplicateEmail implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    public void beforeInsert(List<SObject> triggerNew) {
        validateDuplicates(triggerNew, null);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        validateDuplicates(triggerNew, triggerOld);
    }

    private void validateDuplicates(List<SObject> triggerNew, List<SObject> triggerOld) {
        Set<Id> accountIds = new Set<Id>();
        Set<String> emails = new Set<String>();
        Set<Integer> indicesToValidate = new Set<Integer>();

        for (Integer i = 0; i < triggerNew.size(); i++) {
            Contact con = (Contact) triggerNew[i];
            if (con.AccountId == null || con.Email == null) {
                continue;
            }

            if (triggerOld != null) {
                Contact oldCon = (Contact) triggerOld[i];
                if (con.Email == oldCon.Email && con.AccountId == oldCon.AccountId) {
                    continue;
                }
            }

            indicesToValidate.add(i);
            accountIds.add(con.AccountId);
            emails.add(con.Email);
        }

        if (indicesToValidate.isEmpty()) {
            return;
        }

        // Map to store DB duplicates: Key = accountId|email.toLowerCase(), Value = Set of Contact IDs
        Map<String, Set<Id>> dbDuplicates = new Map<String, Set<Id>>();
        for (Contact con : [SELECT Id, AccountId, Email FROM Contact WHERE AccountId IN :accountIds AND Email IN :emails]) {
            String key = (con.AccountId + '|' + con.Email).toLowerCase();
            if (!dbDuplicates.containsKey(key)) {
                dbDuplicates.put(key, new Set<Id>());
            }
            dbDuplicates.get(key).add(con.Id);
        }

        Set<String> processedInBatch = new Set<String>();

        for (Integer i = 0; i < triggerNew.size(); i++) {
            if (!indicesToValidate.contains(i)) {
                continue;
            }

            Contact con = (Contact) triggerNew[i];
            String key = (con.AccountId + '|' + con.Email).toLowerCase();
            Boolean hasConflict = false;

            // 1. Check against database records (excluding the current record itself)
            if (dbDuplicates.containsKey(key)) {
                Set<Id> ids = dbDuplicates.get(key);
                for (Id id : ids) {
                    if (id != con.Id) {
                        hasConflict = true;
                        break;
                    }
                }
            }

            // 2. Check against records already processed in this batch
            if (!hasConflict && processedInBatch.contains(key)) {
                hasConflict = true;
            }

            if (hasConflict) {
                con.addError('Another contact on this account already uses this email address.');
            } else {
                processedInBatch.add(key);
            }
        }
    }
}
