public class TA_Lead_NormalizeContactInfo implements TriggerAction.BeforeInsert {
    /**
     * Normalizes Lead contact information before the record is first saved.
     * 
     * @param triggerNew List of Leads being inserted.
     */
    public void beforeInsert(List<SObject> triggerNew) {
        for (SObject so : triggerNew) {
            Lead lead = (Lead)so;

            // Clean Email: trim whitespace and lowercase
            if (lead.Email != null) {
                lead.Email = lead.Email.trim().toLowerCase();
            }

            // Clean Company: trim whitespace
            if (lead.Company != null) {
                lead.Company = lead.Company.trim();
            }

            // Default LeadSource to 'Web' if blank
            if (String.isBlank(lead.LeadSource)) {
                lead.LeadSource = 'Web';
            }
        }
    }
}
