public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {
    private static Set<Id> processedOppIds = new Set<Id>();

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        List<Task> tasksToInsert = new List<Task>();
        Map<Id, SObject> oldMap = new Map<Id, SObject>(triggerOld);

        for (SObject sobjNew : triggerNew) {
            Opportunity oppNew = (Opportunity)sobjNew;
            Opportunity oppOld = (Opportunity)oldMap.get(oppNew.Id);

            if (oppNew.Amount != oppOld.Amount && !processedOppIds.contains(oppNew.Id)) {
                tasksToInsert.add(new Task(
                    Subject = 'Amount changed',
                    WhatId = oppNew.Id,
                    Status = 'Completed'
                ));
                processedOppIds.add(oppNew.Id);
            }
        }

        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }
    }
}
